class 猫粮碗:
    _唯一的一只 = None

    def __new__(cls):
        if cls._唯一的一只 is None:
            cls._唯一的一只 = super().__new__(cls)
            cls._唯一的一只.存量 = 0
        return cls._唯一的一只


